parameters.jsCode:
// Get the risk analysis text written by the AI
const text = $('Risk Analysis LLM').first().json.text;

// Find "LABEL: ..." and take everything until the next LABEL
const grab = (label) => {
  const m = text.match(new RegExp(label + ':\\s*([\\s\\S]*?)(?=\\n[A-Z_]+:|$)'));
  return m ? m[1].trim() : '';
};

// Build the object in the exact shape the backend expects
return [{ json: {
  date: new Date().toISOString().slice(0, 10),
  competitors: $('AI Agent (Get Competitors List)').first().json.output,
  summary: $('Summarization LLM').first().json.text,
  risk_level: grab('RISK_LEVEL').replace(/[^A-Z]/g, ''),
  confidence: grab('CONFIDENCE').replace(/[^A-Z]/g, ''),
  top_reasons: grab('TOP_REASONS'),
  impact_areas: grab('IMPACT_AREAS'),
  recommended_actions: grab('RECOMMENDED_ACTIONS'),
}}];
